      "name": "subquery_wrap",
      "kind": "query_wrap",
      "template": "SELECT * FROM ({q}) AS llm_sub",
      "argument": "Wrapping the entire statement as a derived table preserves all rows and columns, including duplicates, because SELECT * projects every column from the subquery without filtering, aggregation, or changing bag semantics."
    },
    {
      "name": "cte_wrap",
      "kind": "query_wrap",
      "template": "WITH llm_cte AS ({q}) SELECT * FROM llm_cte",
      "argument": "Defining the entire statement as a common table expression and selecting all its rows preserves the multiset of rows and columns; the CTE is evaluated once and SELECT * returns every row including duplicates."
    },
    {
      "name": "is_true_wrap",
      "kind": "predicate_wrap",
      "template": "({p}) IS TRUE",
      "argument": "In SQL three-valued logic, WHERE keeps only rows where the predicate is TRUE. For a boolean predicate p, p IS TRUE is TRUE exactly when p is TRUE, FALSE when p is FALSE, and FALSE when p is UNKNOWN. Thus the set of admitted rows is identical."
    }
  ],
  "prediction": [
    {
      "rule": "subquery_wrap",
      "equivalent_on": ["duckdb", "datafusion", "sqlite", "postgres"],
      "why": "All listed engines support derived tables with aliases and preserve the multiset of rows returned by a SELECT * projection."
    },
    {
      "rule": "cte_wrap",
      "equivalent_on": ["duckdb", "datafusion", "sqlite", "postgres"],
      "why": "All listed engines support common table expressions wrapping a SELECT statement and preserve the multiset of rows when selecting all columns from the CTE."
    },
    {
      "rule": "is_true_wrap",
      "equivalent_on": ["duckdb", "datafusion", "sqlite", "postgres"],
      "why": "All listed engines implement SQL three-valued logic and the IS TRUE predicate, which filters out FALSE and UNKNOWN exactly as the original WHERE predicate does."
    }
  ]
